template:
use std::cell::RefCell;

fn safe_read(cell: &RefCell<i32>) -> Option<i32> {
    match cell.⟦slot1⟧() {
        Ok(guard) => Some(⟦slot2⟧),
        Err(_) => None,
    }
}

fn main() {
    let cell = RefCell::new(42);
    let _b = cell.borrow_mut();
    println!("{:?}", safe_read(&cell));
}

tests:
#[test]
fn reads_when_unborrowed() {
    let cell = RefCell::new(42);
    assert_eq!(safe_read(&cell), Some(42));
}

#[test]
fn handles_active_mut_borrow() {
    let cell = RefCell::new(42);
    let _guard = cell.borrow_mut();
    assert_eq!(safe_read(&cell), None);
}

#[test]
fn allows_shared_borrow() {
    let cell = RefCell::new(42);
    let _guard = cell.borrow();
    assert_eq!(safe_read(&cell), Some(42));
}
